<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class FxConversion extends Model { use HasUuids; public $incrementing=false; protected $keyType='string'; protected $fillable=['quote_id','user_id','source_wallet_currency_account_id','target_wallet_currency_account_id','source_currency_code','target_currency_code','source_amount_minor','target_amount_minor','fee_minor','exchange_rate','status','ledger_transaction_id','idempotency_key_id','sandbox_only','failure_reason','completed_at','metadata']; protected $casts=['sandbox_only'=>'boolean','completed_at'=>'datetime','metadata'=>'array']; public function quote(): BelongsTo { return $this->belongsTo(FxQuote::class); } public function legs(): HasMany { return $this->hasMany(FxConversionLeg::class,'conversion_id'); } public function ledgerTransaction(): BelongsTo { return $this->belongsTo(LedgerTransaction::class,'ledger_transaction_id'); } }
